from pathlib import Path

p = Path('ClockTimer.js')
s = p.read_text()

def once(old, new, label):
    global s
    n = s.count(old)
    if n != 1:
        raise SystemExit(f'{label}: expected 1 match, found {n}')
    s = s.replace(old, new, 1)

# Retain both the literal start() inputs and an effective post-start snapshot used by reset().
once('''        #standardDuration;\n\n        #percentGoal =''', '''        #standardDuration;\n\n        #originalStartArguments;\n\n        #startResetState;\n\n        #restoringStartState =\n            false;\n\n        #percentGoal =''', 'start snapshot fields')

# reset() participates in async batching.
once('''                        case "insert":\n                            this.insert(operation.args);\n                            break;\n\n                        case "replaceWithNext":''', '''                        case "insert":\n                            this.insert(operation.args);\n                            break;\n\n                        case "reset":\n                            this.reset();\n                            break;\n\n                        case "replaceWithNext":''', 'async reset dispatch')

# Capture literal inputs before start() normalizes/defaults them.
once('''        start({\n            standardTime,\n            creationTime,\n            startTime,\n            scheduledStart\n        } = {}) {\n            if (''', '''        start({\n            standardTime,\n            creationTime,\n            startTime,\n            scheduledStart\n        } = {}) {\n            const suppliedStartArguments = {\n                standardTime,\n                creationTime,\n                startTime,\n                scheduledStart\n            };\n\n            if (''', 'capture supplied start args')

# Snapshot the effective state at the end of a successful start. This occurs before later setters/insert/overwrite calls.
once('''            this.#stopTickTimer();\n            this.#scheduleNextTick();\n\n            return this;\n        }\n\n        #typeExtendsCalculatedEndTime(type) {''', '''            this.#stopTickTimer();\n            this.#scheduleNextTick();\n\n            const effectiveStartTime =\n                this.#formatTimelineTime(\n                    startTimeMilliseconds\n                );\n\n            const preservedOriginalArguments =\n                this.#originalStartArguments;\n\n            this.#startResetState = {\n                args: {\n                    standardTime:\n                        this.#standardTime,\n                    creationTime:\n                        this.#creationTime,\n                    startTime:\n                        effectiveStartTime,\n                    scheduledStart:\n                        this.#scheduledStart\n                },\n                percentGoal:\n                    this.getAttribute(\n                        "percent-goal"\n                    ),\n                insertedRanges:\n                    this.#cloneInsertedRecords(\n                        this.#insertedRanges\n                    ),\n                openEndedRangeId:\n                    this.#openEndedRange?.id,\n                openEndedLastTick:\n                    this.#openEndedLastTick\n            };\n\n            this.#originalStartArguments =\n                this.#restoringStartState\n                    ? preservedOriginalArguments\n                    : {\n                        ...suppliedStartArguments\n                    };\n\n            return this;\n        }\n\n        #cloneInsertedRecords(records) {\n            return records.map(record => ({\n                ...record,\n                startDate:\n                    new Date(\n                        record.startDate.getTime()\n                    ),\n                endDate:\n                    record.endDate\n                        ? new Date(\n                            record.endDate.getTime()\n                        )\n                        : undefined,\n                otherAttributes: {\n                    ...(record.otherAttributes ?? {})\n                },\n                preservedAttributes:\n                    (record.preservedAttributes ?? [])\n                        .map(snapshot => ({\n                            ...snapshot,\n                            attributes: {\n                                ...(snapshot.attributes ?? {})\n                            }\n                        }))\n            }));\n        }\n\n        reset() {\n            if (\n                this.#updatesSuspended &&\n                !this.#processingAsyncBatch\n            ) {\n                if (!this.#startResetState) {\n                    throw new Error(\n                        "reset() cannot be called before start() or after clear()."\n                    );\n                }\n\n                this.#queueAsyncOperation({\n                    type: "reset"\n                });\n\n                return this;\n            }\n\n            if (!this.#startResetState) {\n                throw new Error(\n                    "reset() cannot be called before start() or after clear()."\n                );\n            }\n\n            const snapshot = {\n                args: {\n                    ...this.#startResetState.args\n                },\n                percentGoal:\n                    this.#startResetState.percentGoal,\n                insertedRanges:\n                    this.#cloneInsertedRecords(\n                        this.#startResetState.insertedRanges\n                    ),\n                openEndedRangeId:\n                    this.#startResetState.openEndedRangeId,\n                openEndedLastTick:\n                    this.#startResetState.openEndedLastTick\n            };\n\n            const originalArguments =\n                this.#originalStartArguments\n                    ? {\n                        ...this.#originalStartArguments\n                    }\n                    : undefined;\n\n            this.#insertedRanges =\n                snapshot.insertedRanges;\n\n            this.#openEndedRange =\n                snapshot.openEndedRangeId\n                    ? this.#insertedRanges.find(\n                        record =>\n                            record.id ===\n                                snapshot.openEndedRangeId\n                    )\n                    : undefined;\n\n            this.#openEndedLastTick =\n                snapshot.openEndedLastTick;\n\n            if (snapshot.percentGoal === null) {\n                this.removeAttribute(\n                    "percent-goal"\n                );\n            }\n            else {\n                this.setAttribute(\n                    "percent-goal",\n                    snapshot.percentGoal\n                );\n            }\n\n            this.#restoringStartState =\n                true;\n\n            try {\n                this.start(\n                    snapshot.args\n                );\n            }\n            finally {\n                this.#restoringStartState =\n                    false;\n\n                this.#originalStartArguments =\n                    originalArguments;\n            }\n\n            return this;\n        }\n\n        #typeExtendsCalculatedEndTime(type) {''', 'start snapshot and reset')

# A user-visible clear invalidates the reset baseline and preserved literal inputs. Internal start() clear is followed by a new snapshot.
once('''            this.#standardDuration =\n                undefined;\n\n            this.#startedAtEpoch =''', '''            this.#standardDuration =\n                undefined;\n\n            if (!this.#restoringStartState) {\n                this.#originalStartArguments =\n                    undefined;\n\n                this.#startResetState =\n                    undefined;\n            }\n\n            this.#startedAtEpoch =''', 'clear reset state')

# A normal start() invokes clear(); allow it to build a fresh snapshot after clear without preserving an old baseline.
# No extra handling is needed: the supplied args were captured before clear and the new snapshot is written at the end.

for needle in [
    '#originalStartArguments;',
    '#startResetState;',
    'reset() {',
    'case "reset":',
    '#cloneInsertedRecords(records)'
]:
    if needle not in s:
        raise SystemExit(f'missing expected code: {needle}')

p.write_text(s)
